import csv
import io
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation


def summarize_csv(text: str) -> dict:
    if text.strip() == '':
        return {}

    reader = csv.reader(io.StringIO(text))
    rows = list(reader)

    if not rows:
        return {}

    if rows[0] != ['sku', 'amount']:
        raise ValueError("Header must be exactly 'sku,amount'")

    agg: dict[str, Decimal] = {}

    for row in rows[1:]:
        if not row or all(f.strip() == '' for f in row):
            continue

        if len(row) != 2:
            raise ValueError("Each data row must have exactly 2 fields")

        sku = row[0].strip()
        amt_str = row[1].strip()

        if sku == '':
            raise ValueError("SKU must not be empty")

        try:
            amt = Decimal(amt_str)
        except (InvalidOperation, ValueError):
            raise ValueError(f"Malformed amount: {amt_str!r}")

        if not amt.is_finite():
            raise ValueError(f"Amount must be finite: {amt_str!r}")

        agg[sku] = agg.get(sku, Decimal('0')) + amt

    return {
        sku: str(agg[sku].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        for sku in sorted(agg)
    }
```

